const input = $json;

// Detectar coordenadas en texto
function coordsFromText(text) {
  const regex = /(-?\d{1,3}\.\d+)[, ]+(-?\d{1,3}\.\d+)/;
  const m = text.match(regex);
  if (!m) return null;
  return { lat: parseFloat(m[1]), lon: parseFloat(m[2]) };
}

let type = "unknown";
let parsed = {};

if (input.content_type === "text" && input.content) {
  const coords = coordsFromText(input.content);
  if (coords) {
    type = "location";
    parsed = { ...coords, raw: input.content };
  } else {
    type = "text";
    parsed = { text: input.content };
  }
}

else if (input.content_type?.includes("image") || input.media_url) {
  type = "image";
  parsed = { url: input.media_url };
}

else if (input.content_type?.includes("audio")) {
  type = "audio";
  parsed = { url: input.media_url };
}

else if (input.content_type === "location") {
  type = "location";
  parsed = {
    lat: input.location.latitude,
    lon: input.location.longitude,
    address: input.location.address
  };
}

return [{
  json: {
    type,
    parsed,
    raw: input
  }
}];

for (const item of $input.all()) {
	const body = item.json.message || item.json;

	item.json.messageType = "text";

	// Imagen
	if (body.attachments?.[0]?.file_type?.startsWith("image")) {
		item.json.messageType = "image";
		item.json.image_url = body.attachments[0].data_url;
	}

	// Audio
	if (body.attachments?.[0]?.file_type?.startsWith("audio")) {
		item.json.messageType = "audio";
		item.json.audio_url = body.attachments[0].data_url;
	}

	// Ubicación
	if (body.location) {
		item.json.messageType = "location";
		item.json.location = body.location;
	}

	// Texto
	if (body.content) {
		item.json.text = body.content;
	}

}

return $input.all();

